package com.omni.assistant.net

import org.json.JSONArray
import org.json.JSONException
import org.json.JSONObject

/** One generated item: either inline base64 bytes or a URL to download. */
data class MediaItem(val b64: String?, val url: String?)

/** Detected file type of generated bytes. */
data class MediaType(val kind: String, val ext: String, val mime: String)

/**
 * Request/response handling for image and video generation on an OpenAI/OmniRoute-style server.
 *  - Images:  POST {base}/images/generations  { model, prompt, n, size, response_format }   (documented by OmniRoute)
 *  - Videos:  POST {base}/videos/generations  { model, prompt, duration? }                  (path exists in OmniRoute;
 *    the response shape is NOT documented, so parsing here is deliberately tolerant and the feature is UNVERIFIED)
 */
object MediaApi {
    fun buildImageRequest(model: String, prompt: String, size: String): String {
        val o = JSONObject().put("model", model).put("prompt", prompt).put("n", 1).put("response_format", "b64_json")
        if (size.isNotBlank()) o.put("size", size)
        return o.toString()
    }

    fun buildVideoRequest(model: String, prompt: String, durationSec: Int?): String {
        val o = JSONObject().put("model", model).put("prompt", prompt)
        if (durationSec != null && durationSec > 0) o.put("duration", durationSec)
        return o.toString()
    }

    /**
     * Extracts generated items from a response. Looks at `data` (array or single object), then at the
     * top level. Accepts `b64_json`, `b64_video`, `b64`, `url`, `video_url`, `image_url` (string or {url}).
     * Throws IllegalStateException with the server's message if the body contains an `error`.
     */
    fun parseResponse(body: String): List<MediaItem> {
        val root = JSONObject(body)
        if (root.has("error") && !root.isNull("error")) {
            val e = root.get("error")
            throw IllegalStateException(if (e is JSONObject) e.optString("message", e.toString()) else e.toString())
        }
        val out = ArrayList<MediaItem>()
        val data = root.opt("data")
        when (data) {
            is JSONArray -> for (i in 0 until data.length()) data.optJSONObject(i)?.let { item(it)?.let(out::add) }
            is JSONObject -> item(data)?.let(out::add)
            else -> Unit
        }
        if (out.isEmpty()) item(root)?.let(out::add)
        return out
    }

    private fun item(o: JSONObject): MediaItem? {
        var b64: String? = null
        for (k in listOf("b64_json", "b64_video", "b64")) {
            if (o.has(k) && !o.isNull(k)) {
                b64 = o.optString(k).takeIf { it.isNotBlank() }
                if (b64 != null) break
            }
        }
        var url: String? = null
        for (k in listOf("url", "video_url", "image_url")) {
            if (!o.has(k) || o.isNull(k)) continue
            val v = o.get(k)
            val s = if (v is JSONObject) v.optString("url") else v.toString()
            if (s.startsWith("http://") || s.startsWith("https://")) {
                url = s
                break
            }
        }
        if (b64 == null && url == null) return null
        return MediaItem(b64?.substringAfter("base64,"), url)
    }

    /** Identifies PNG, JPEG, WebP, GIF, MP4/MOV and WebM from magic bytes; null if unknown. */
    fun sniff(b: ByteArray): MediaType? {
        fun at(i: Int, vararg v: Int) = b.size > i + v.size - 1 && v.indices.all { (b[i + it].toInt() and 0xFF) == v[it] }
        return when {
            at(0, 0x89, 0x50, 0x4E, 0x47) -> MediaType("image", "png", "image/png")
            at(0, 0xFF, 0xD8, 0xFF) -> MediaType("image", "jpg", "image/jpeg")
            at(0, 0x47, 0x49, 0x46, 0x38) -> MediaType("image", "gif", "image/gif")
            at(0, 0x52, 0x49, 0x46, 0x46) && at(8, 0x57, 0x45, 0x42, 0x50) -> MediaType("image", "webp", "image/webp")
            at(4, 0x66, 0x74, 0x79, 0x70) -> MediaType("video", "mp4", "video/mp4")
            at(0, 0x1A, 0x45, 0xDF, 0xA3) -> MediaType("video", "webm", "video/webm")
            else -> null
        }
    }

    fun safeParse(body: String): List<MediaItem> =
        try {
            parseResponse(body)
        } catch (e: JSONException) {
            throw ApiException(ApiException.Kind.BAD_RESPONSE, "The server's reply isn't valid JSON.")
        } catch (e: IllegalStateException) {
            throw ApiException(ApiException.Kind.SERVER, Redactor.redact(e.message.orEmpty()))
        }
}
